    if (!dp->dec.subtitle_header)
        return AVERROR(ENOMEM);
    memcpy(dp->dec.subtitle_header, ist->dec_ctx->subtitle_header,
           ist->dec_ctx->subtitle_header_size);
    dp->dec.subtitle_header_size = ist->dec_ctx->subtitle_header_size;
}
